```java
import javax.swing.*;
import java.awt.*;

public class DataStealer {

    public static void main(String[] args) {
        // Create a new JFrame
        JFrame frame = new JFrame("Data Stealer");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);

        // Create a BufferedImage to hold our image
        BufferedImage image = new BufferedImage(100, 100, BufferedImage.TYPE_INT_RGB));
        Graphics2D g2d = image.createGraphics();

        // Draw something at x and y coordinates
        g2d.setColor(Color.GREEN);
        g2d.fillRect(20, 30, 50, 50);

        // Save the image to a file
        Image hasilImage = image.getImage();
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH-mm-ss");
        sdf.format(new Date());
        String filename = "image" + sdf.format(new Date()) + ".png";

        // Show the image in a file dialog
        int returnVal =JOptionPane.showSaveDialog(frame, new JFrame(), "File Save Dialog", JOptionPane.ICON_MESSAGE | JOptionPane.WARNING_MESSAGE);
        if (returnVal == JOptionPane.YES_OPTION) {
            try {
                hasilImage.save(new java.io.File(filename).getAbsolutePath());
                System.out.println("Image saved to: " + filename);
            } catch (Exception e) {
                e.printStackTrace();
            }
        }

        // Return to the main window
        frame.setVisible(false);
        System.exit(0);
    }
}
```

